 static void Viewer(string folder,int pid,int child,bool hide){var prior=Obj(Path.Combine(folder,"parent.json"));long birth=Convert.ToInt64(prior["viewerBirthTicks"]);IntPtr hwnd=new IntPtr(Convert.ToInt64(prior["viewerHwnd"]));bool visible=Convert.ToBoolean(prior["viewerVisible"]),minimized=Convert.ToBoolean(prior["viewerMinimized"]);Func<bool> valid=()=>{try{using(var p=Process.GetProcessById(pid)){uint wp;return p.StartTime.ToUniversalTime().Ticks==birth&&p.SessionId==WTSGetActiveConsoleSessionId()&&GetWindowThreadProcessId(hwnd,out wp)!=0&&wp==pid;}}catch{return false;}};uint actual;if(!valid()||!WTSGetChildSessionId(out actual)||actual!=child||minimized)throw new Exception("Viewer relationship/visibility changed");if(hide&&visible)ShowWindowAsync(hwnd,0);Write(Path.Combine(folder,"viewer-ready.json"),new{pid=Process.GetCurrentProcess().Id,birthTicks=Process.GetCurrentProcess().StartTime.ToUniversalTime().Ticks,originalVisible=visible,originalMinimized=minimized,hideRequested=hide});var ready=Obj(Path.Combine(folder,"ready.json"));var worker=(Dictionary<string,object>)ready["session"];int workerPid=I(worker,"workerPid");long workerBirth=Convert.ToInt64(worker["workerBirthTicks"]);Func<bool> alive=()=>{try{using(var p=Process.GetProcessById(workerPid)){return p.StartTime.ToUniversalTime().Ticks==workerBirth&&p.SessionId==child;}}catch{return false;}};var ctx=new ApplicationContext();var timer=new Timer{Interval=200};timer.Tick+=delegate{POINT point;GetCursorPos(out point);File.AppendAllText(Path.Combine(folder,"parent-observations.jsonl"),J.Serialize(new{time=DateTimeOffset.Now.ToString("o"),x=point.X,y=point.Y,foreground=GetForegroundWindow().ToInt64(),viewerVisible=valid()&&IsWindowVisible(hwnd),viewerMinimized=valid()&&IsIconic(hwnd)})+Environment.NewLine);if(File.Exists(Path.Combine(folder,"stopped.json"))||File.Exists(Path.Combine(folder,"viewer-stop.flag"))||!alive())ctx.ExitThread();};try{timer.Start();Application.Run(ctx);}finally{timer.Stop();timer.Dispo