 static void Fixture(string file){var f=new Form{Text="Desktop Session Helper owned fixture",Width=480,Height=280,StartPosition=FormStartPosition.Manual,Location=new Point(100,100)};var label=new Label{Text="Owned helper fixture — input is confined to this child session",Location=new Point(20,20),Width=430};var input=new TextBox{Location=new Point(20,70),Width=400};var button=new Button{Text="Record click",Location=new Point(20,120),Width=150};int clicks=0;var keys=new List<string>();Action save=()=>Write(file,new{text=input.Text,clicks=clicks,keys=keys.ToArray(),selectionStart=input.SelectionStart,selectionLength=input.SelectionLength,shortcutsEnabled=input.ShortcutsEnabled,multiline=input.Multiline,pid=Process.GetCurrentProcess().Id,sessionId=Process.GetCurrentProcess().SessionId});input.PreviewKeyDown+=delegate(object sender,PreviewKeyDownEventArgs e){keys.Add(e.KeyData.ToString());save();};input.TextChanged+=delegate{save();};button.Click+=delegate{clicks++;save();};f.Controls.AddRange(new Control[]{label,input,button});f.Shown+=delegate{input.Focus();save();};var t=new Timer{Interval=120000};t.Tick+=delegate{f.Close();};t.Start();Application.Run(f);t.Dispose();}
